import { useState, useMemo, useCallback, memo, lazy, Suspense } from 'react';

const ExpensiveCard = memo(function ExpensiveCard({ data, onClick }) {
  return (
    <div className="card" onClick={() => onClick(data.id)}>
      <h3>{data.title}</h3>
      <p>{data.description}</p>
      <span className="price">${data.price}</span>
    </div>
  );
});

function DataDashboard({ items, filter }) {
  const filteredItems = useMemo(() => {
    console.log('Filtering items...');
    return items
      .filter(item => item.category === filter || filter === 'all')
      .sort((a, b) => b.price - a.price);
  }, [items, filter]);

  const total = useMemo(() => {
    return filteredItems.reduce((sum, item) => sum + item.price, 0);
  }, [filteredItems]);

  return (
    <div>
      <h2>Total: ${total.toFixed(2)}</h2>
      <div className="grid">
        {filteredItems.map(item => (
          <ExpensiveCard key={item.id} data={item} onClick={(id) => console.log('Clicked:', id)} />
        ))}
      </div>
    </div>
  );
}

function SearchResults({ query, allItems }) {
  const [selectedId, setSelectedId] = useState(null);

  const results = useMemo(() => {
    if (!query) return allItems;
    const lower = query.toLowerCase();
    return allItems.filter(item =>
      item.name.toLowerCase().includes(lower) ||
      item.description.toLowerCase().includes(lower)
    );
  }, [query, allItems]);

  const handleSelect = useCallback((id) => {
    setSelectedId(id);
  }, []);

  return (
    <div>
      {results.map(item => (
        <div key={item.id} onClick={() => handleSelect(item.id)} className={selectedId === item.id ? 'selected' : ''}>
          {item.name}
        </div>
      ))}
    </div>
  );
}

function VirtualList({ items, itemHeight = 50 }) {
  const [scrollTop, setScrollTop] = useState(0);
  const containerHeight = 400;

  const visibleStart = Math.floor(scrollTop / itemHeight);
  const visibleCount = Math.ceil(containerHeight / itemHeight) + 2;
  const visibleItems = items.slice(visibleStart, visibleStart + visibleCount);

  const handleScroll = useCallback((e) => {
    setScrollTop(e.target.scrollTop);
  }, []);

  return (
    <div className="virtual-list" style={{ height: containerHeight, overflow: 'auto' }} onScroll={handleScroll}>
      <div style={{ height: items.length * itemHeight, position: 'relative' }}>
        {visibleItems.map((item, idx) => (
          <div key={item.id} style={{
            position: 'absolute',
            top: (visibleStart + idx) * itemHeight,
            height: itemHeight,
            padding: '10px'
          }}>
            {item.name}
          </div>
        ))}
      </div>
    </div>
  );
}

const HeavyComponent = lazy(() => import('./HeavyComponent'));

function LazyLoader() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <HeavyComponent />
    </Suspense>
  );
}
